package solution

import (
	"math"
	"sync"
	"testing"
)

func TestLedgerValidationOrderingAndCopies(t *testing.T) {
	var l Ledger
	bad := []struct{k string; v float64; tick int64}{{"",1,0},{"x",1,-1},{"x",math.NaN(),0},{"x",math.Inf(1),0},{"x",math.Inf(-1),0}}
	for _, b := range bad { if err := l.Append(b.k,b.v,b.tick); err == nil { t.Fatalf("accepted %+v", b) } }
	if h, ok := l.History("x"); ok || h.Values != nil || h.Ticks != nil || h.Min != 0 || h.Max != 0 { t.Fatalf("missing history = %+v, %v", h, ok) }
	if m, ok := l.Mean("x"); ok || m != 0 { t.Fatalf("missing mean = %v, %v", m, ok) }
	for _, x := range []struct{v float64; tick int64}{{3,1},{-1,1},{5,4}} { if err := l.Append("x",x.v,x.tick); err != nil { t.Fatal(err) } }
	if err := l.Append("x",99,3); err == nil { t.Fatal("accepted decreasing tick") }
	h, ok := l.History("x")
	if !ok || len(h.Values)!=3 || h.Values[0]!=3 || h.Values[1]!=-1 || h.Values[2]!=5 || h.Ticks[0]!=1 || h.Ticks[1]!=1 || h.Ticks[2]!=4 || h.Min!=-1 || h.Max!=5 { t.Fatalf("bad history: %+v, %v", h, ok) }
	h.Values[0]=100; h.Ticks[0]=100
	h2, _ := l.History("x")
	if h2.Values[0]!=3 || h2.Ticks[0]!=1 { t.Fatal("History aliases storage") }
	if mean, ok := l.Mean("x"); !ok || mean != 7.0/3.0 { t.Fatalf("Mean = %v, %v", mean, ok) }
}

func TestLedgerConcurrentKeys(t *testing.T) {
	l := NewLedger()
	const n=30
	var wg sync.WaitGroup
	for i:=0;i<n;i++ { i:=i; wg.Add(1); go func(){ defer wg.Done(); if err:=l.Append("k"+string(rune('A'+i)),float64(i),0); err!=nil { t.Errorf("Append: %v",err) } }() }
	wg.Wait()
	for i:=0;i<n;i++ { h,ok:=l.History("k"+string(rune('A'+i))); if !ok || len(h.Values)!=1 || h.Values[0]!=float64(i) { t.Fatalf("entry %d: %+v, %v",i,h,ok) } }
}

package solution

import (
	"math"
	"testing"
)

func TestReviewFiniteMean0327(t *testing.T) {
	l := NewLedger()
	for i := 0; i < 2; i++ { if err := l.Append("a", math.MaxFloat64, int64(i)); err != nil { t.Fatal(err) } }
	got, ok := l.Mean("a")
	if !ok || got != math.MaxFloat64 { t.Fatalf("mean of two identical finite values=%v ok=%v, want MaxFloat64", got, ok) }
}

