	l.mu.RLock(); defer l.mu.RUnlock()
	vs, ok := l.values[key]; if !ok { return History{}, false }
	out := History{Values:vs, Ticks:append([]int64(nil), l.ticks[key]...), Min:vs[0], Max:vs[0]}
	for _, v := range vs[1:] { if v < out.Min { out.Min = v }; if v > out.Max { out.Max = v } }
	return out, true
}
func (l *Ledger) Mean(key string) (float64, bool) {
	l.mu.RLock(); defer l.mu.RUnlock(); vs, ok := l.values[key]; if !ok { return 0, false }
	var sum float64; for _, v := range vs { sum += v }; return sum/float64(len(vs)), true
}

